// NOTE: n8n webhook v2 wraps POST body in .body — never remove the raw.body unwrap below
const raw = $input.first().json;
const body = raw.body || raw;          // webhook v2 puts POST body here
const d = body.data || body;
if (!d.lactateData || !Array.isArray(d.lactateData) || d.lactateData.length < 3) {
  throw new Error('Zu wenig Laktat-Messpunkte (min. 3)');
}
return [{ json: {
  sessionId:         d.sessionId        || null,
  customerId:        d.customerId       || null,
  customerName:      d.customerName     || 'Athlet',
  unit:              d.unit             || 'watt',
  currentMethod:     d.currentMethod    || 'dmax',
  zoneModel:         d.zoneModel        || '5-zones',
  stepCount:         d.stepCount        || d.lactateData.length,
  testDevice:        d.testDevice       || 'bike',
  lactateData:       d.lactateData,
  currentThresholds: d.currentThresholds || { lt1: null, lt2: null },
  vt1:               d.vt1    || null,
  vt2:               d.vt2    || null,
  vo2max:            d.vo2max != null ? d.vo2max : null,
  timestamp:         d.timestamp        || new Date().toISOString()
}}];

// Read session context from Parse Context Fields (agent output has no lactateData)
const ctx = $('Parse Context Fields').first().json;
const lactateData = ctx.lactateData || [];
const all = $input.all();

function evalPiecewise(params, v) {
  const { L0, m, A, k, v_ref, v_break } = params;
  const L_break = L0 + m * (v_break - v_ref);
  if (v <= v_break) return L0 + m * (v - v_ref);
  return L_break + A * (Math.exp(k * (v - v_break)) - 1);
}

function generateCurve(params) {
  const powers = lactateData.map(d => d.power || d.load || 0).filter(p => p > 0);
  if (powers.length < 2) return null;
  const minP = Math.min(...powers), maxP = Math.max(...powers);
  const curve = [];
  for (let i = 0; i < 50; i++) {
    const p = minP + (maxP - minP) * i / 49;
    curve.push({ power: Math.round(p * 10) / 10, lactate: Math.max(0, Math.round(evalPiecewise(params, p) * 100) / 100) });
  }
  return curve;
}

function extractPower(val) {
  if (val == null) return null;
  if (typeof val === 'number' && val > 5) return val;
  if (typeof val === 'object') {
    const p = val.power ?? val.load ?? val.v;
    if (typeof p === 'number' && p > 5) return p;
  }
  return null;
}

function lactatAtPower(power) {
  const sorted = [...lactateData].sort((a,b) => (a.power||a.load||0) - (b.power||b.load||0));
  for (let i = 0; i < sorted.length - 1; i++) {
    const p0 = sorted[i].power||sorted[i].load||0, p1 = sorted[i+1].power||sorted[i+1].load||0;
    if (power >= p0 && power <= p1 && p1 > p0) {
      const t = (power - p0) / (p1 - p0);
      return sorted[i].lactate + t * (sorted[i+1].lactate - sorted[i].lactate);
    }
  }
  return null;
}

function buildPoint(power, modelParams) {
  if (power == null) return null;
  const lactate = modelParams ? Math.max(0, evalPiecewise(modelParams, power)) : (lactatAtPower(power) ?? 0);
  return { power: Math.round(power), lactate: Math.round(lactate * 100) / 100 };
}

let bestResult = null;
let curve = null;
const methodsArray = [];
const agentErrors = [];

for (const item of all) {
  const out = item.json;

  // Collect errors from agents that failed (e.g. quota exceeded)
  if (out.error) {
    const errMsg = typeof out.error === 'string' ? out.error
      : (out.error.message || JSON.stringify(out.error));
    agentErrors.push(errMsg);
    continue;
  }

  let p = null;
  if (out.ai_lt1 !== undefined || out.ai_lt2 !== undefined) {
    p = out;
  } else {
    const rawText = (typeof out.output === 'string' ? out.output : '') || (typeof out.text === 'string' ? out.text : '');
    if (rawText) {
      const m = rawText.match(/\{[\s\S]*\}/);
      if (m) { try { p = JSON.parse(m[0]); } catch(e) {} }
    }
  }

  if (!p) continue;

  const modelParams = (p.ai_curve && p.ai_curve.parameters && p.ai_curve.v_break != null) ? {
    L0: p.ai_curve.parameters.L0, m: p.ai_curve.parameters.m,
    A:  p.ai_curve.parameters.A,  k: p.ai_curve.parameters.k,
    v_ref: p.ai_curve.parameters.v_ref, v_break: p.ai_curve.v_break
  } : null;

  if (!curve && modelParams && modelParams.L0 != null && modelParams.A > 0 && modelParams.k > 0) {
    try { curve = generateCurve(modelParams); } catch(e) {}
  }

  const lt1Power = extractPower(p.ai_lt1);
  const lt2Power = extractPower(p.ai_lt2);
  if ((lt1Power != null || lt2Power != null) && !bestResult) {
    bestResult = {
      lt1: lt1Power != null ? buildPoint(lt1Power, modelParams) : null,
      lt2: lt2Power != null ? buildPoint(lt2Power, modelParams) : null,
      confidence: p.confidence ?? 0.7,
      reasoning: typeof p.reasoning === 'string' ? p.reasoning : ''
    };
  }

  if (p.other_methods && typeof p.other_methods === 'object') {
    for (const [methodKey, methodVal] of Object.entries(p.other_methods)) {
      if (!methodVal) continue;
      const mLt1 = extractPower(methodVal.lt1), mLt2 = extractPower(methodVal.lt2);
      if (mLt1 != null || mLt2 != null) {
        methodsArray.push({
          method: methodKey.replace(/_\d{4}(_\d{4})?$/, '').replace(/_/g, '-'),
          lt1: mLt1 != null ? buildPoint(mLt1, modelParams) : null,
          lt2: mLt2 != null ? buildPoint(mLt2, modelParams) : null,
          confidence: methodVal.confidence ?? 0.5,
          reasoning: methodVal.reasoning || ''
        });
      }
    }
  }
}

// If all agents errored out, return the error to the dashboard
if (!bestResult && agentErrors.length > 0 && lactateData.length === 0) {
  throw new Error(agentErrors[0]);
}

// Algorithmic fallback — runs when AI returns no parseable JSON
if (!bestResult) {
  if (lactateData.length >= 3) {
    const sorted = [...lactateData].sort((a,b) => (a.power||a.load||0) - (b.power||b.load||0));
    const baseLactate = sorted[0].lactate;
    function findPowerAtLactate(target) {
      for (let i = 0; i < sorted.length - 1; i++) {
        const l0 = sorted[i].lactate, l1 = sorted[i+1].lactate;
        const p0 = sorted[i].power||sorted[i].load||0, p1 = sorted[i+1].power||sorted[i+1].load||0;
        if (l0 <= target && l1 >= target && l1 > l0) return Math.round(p0 + (target-l0)/(l1-l0)*(p1-p0));
      }
      return null;
    }
    const errorNote = agentErrors.length > 0 ? ' Fehler: ' + agentErrors.join('; ') : ' AI returned no JSON.';
    bestResult = {
      lt1: (() => { const pw = findPowerAtLactate(baseLactate + 0.5); return pw ? { power: pw, lactate: Math.round((baseLactate+0.5)*100)/100 } : null; })(),
      lt2: (() => { const pw = findPowerAtLactate(baseLactate + 1.5); return pw ? { power: pw, lactate: Math.round((baseLactate+1.5)*100)/100 } : null; })(),
      confidence: 0.3,
      reasoning: 'Algorithmic fallback (Dickhuth +0.5/+1.5 mmol/L): baseline = ' + baseLactate + ' mmol/L.' + errorNote
    };
  } else {
    throw new Error('Kein valides AI-Ergebnis und zu wenig Daten fuer Fallback');
  }
}

return [{ json: {
  success:    true,
  lt1:        bestResult.lt1,
  lt2:        bestResult.lt2,
  vt1:        ctx.vt1    || null,
  vt2:        ctx.vt2    || null,
  vo2max:     ctx.vo2max != null ? ctx.vo2max : null,
  curve:      curve || null,
  method:     'ai',
  confidence: bestResult.confidence,
  reasoning:  bestResult.reasoning,
  methods:    methodsArray.length > 0 ? methodsArray : null,
  agentErrors: agentErrors.length > 0 ? agentErrors : null
}}];

const ctx = $input.first().json;
const NL = String.fromCharCode(10);
const lt1 = ctx.currentThresholds && ctx.currentThresholds.lt1 ? JSON.stringify(ctx.currentThresholds.lt1) : 'null';
const lt2 = ctx.currentThresholds && ctx.currentThresholds.lt2 ? JSON.stringify(ctx.currentThresholds.lt2) : 'null';

const parts = [
  'Analyse this lactate step test. Unit: ' + (ctx.unit || 'watt') + ', Device: ' + (ctx.testDevice || 'bike'),
  'Stages: ' + (ctx.stepCount || 0) + ', Zone model: ' + (ctx.zoneModel || '5-zones'),
  'Lactate data (power, lactate mmol/L, heartRate bpm):',
  JSON.stringify(ctx.lactateData || []),
  'Current thresholds — LT1: ' + lt1 + ', LT2: ' + lt2,
  'Follow the OUTPUT RULE in your system message exactly. Return only valid JSON starting with { and ending with }.'
];

return [{ json: Object.assign({}, ctx, { chatInput: parts.join(NL) }) }];
